From 92664f50f604633b3c262ddcc0bf9e6940c02866 Mon Sep 17 00:00:00 2001
From: Sareh Heidari <sareh.heidari@gmail.com>
Date: Fri, 15 Feb 2019 14:51:58 +0000
Subject: [PATCH 02/25] Initial Cookie Banner

---
 src/app/components/CookieBanner/index.jsx     | 109 ++++++++++++++++++
 .../components/CookieBanner/index.stories.jsx |   4 +
 2 files changed, 113 insertions(+)
 create mode 100644 src/app/components/CookieBanner/index.jsx
 create mode 100644 src/app/components/CookieBanner/index.stories.jsx

diff --git a/src/app/components/CookieBanner/index.jsx b/src/app/components/CookieBanner/index.jsx
new file mode 100644
index 00000000000..113c2910df0
--- /dev/null
+++ b/src/app/components/CookieBanner/index.jsx
@@ -0,0 +1,109 @@
+import React from 'react';
+import styled from 'styled-components';
+import { string } from 'prop-types';
+import { GEL_GREAT_PRIMER, GEL_PICA } from '@bbc/gel-foundations/typography';
+import { C_WHITE } from '@bbc/psammead-styles/colours';
+import { GEL_GROUP_3_SCREEN_WIDTH_MIN } from '@bbc/gel-foundations/breakpoints';
+import { GEL_SPACING, GEL_SPACING_DBL } from '@bbc/gel-foundations/spacings';
+import { FF_NEWS_SANS_REG } from '@bbc/psammead-styles/fonts';
+
+const ConsentDialog = styled.div`
+  background-color: #323232;
+  padding: ${GEL_SPACING_DBL};
+
+  @media (min-width: ${GEL_GROUP_3_SCREEN_WIDTH_MIN}) {
+    &:after {
+      content: \\0020;
+      clear: both;
+      display: block;
+      height: 0;
+      overflow: hidden;
+      visibility: hidden;
+    }
+  }
+`;
+
+const ConsentTitle = styled.h2`
+  ${GEL_GREAT_PRIMER}
+  color: ${C_WHITE};
+  font-family: ${FF_NEWS_SANS_REG};
+
+  @media (min-width: ${GEL_GROUP_3_SCREEN_WIDTH_MIN}) {
+    float: left;
+    width: 20%;
+    margin-right: ${GEL_SPACING_DBL};
+  }
+`;
+
+const ConsentParagraph = styled.p`
+  color: #bebebe;
+  font-family: ${FF_NEWS_SANS_REG};
+
+  @media (min-width: ${GEL_GROUP_3_SCREEN_WIDTH_MIN}) {
+    margin-top: 0;
+    width: 50%;
+    float: left;
+  }
+`;
+
+const ConsentOptionsBox = styled.div`
+  text-align: center;
+
+  @media (min-width: ${GEL_GROUP_3_SCREEN_WIDTH_MIN}) {
+    width: 20%;
+    float: right;
+  }
+`;
+
+const ConsentButton = styled.button`
+  ${GEL_PICA}; //'pica-bold';
+  font-family: ${FF_NEWS_SANS_REG};
+
+  @media (min-width: ${GEL_GROUP_3_SCREEN_WIDTH_MIN}) {
+    display: block;
+  }
+
+  @include mq($until: $consent-dialog-mobile-limit) {
+    width: 25%;
+  }
+
+  background: transparent;
+  border: none;
+  margin: 0 auto;
+  color: #f6a21d;
+  padding-bottom: ${GEL_SPACING};
+`;
+
+const CookieBanner = ({ title, description, accept, reject, id }) => (
+  <ConsentDialog id={id}>
+    <ConsentTitle>{title}</ConsentTitle>
+    <ConsentParagraph>{description}</ConsentParagraph>
+    <ConsentOptionsBox>
+      <ConsentButton on="tap:amp-o-user-consent.accept" role="button">
+        {accept}
+      </ConsentButton>
+      <ConsentButton on="tap:amp-o-user-consent.reject" role="button">
+        {reject}
+      </ConsentButton>
+    </ConsentOptionsBox>
+  </ConsentDialog>
+);
+
+CookieBanner.propTypes = {
+  id: string,
+  title: string,
+  description: string,
+  accept: string,
+  reject: string,
+};
+
+CookieBanner.defaultProps = {
+  title: 'Let us know you agree to cookies',
+  description:
+    'We use cookies to give you the best online experience. Please let us know if you agree to all of these cookies.',
+  accept: 'Accept',
+  reject: 'Reject',
+  id: 'amp-o-user-consent-dialog',
+};
+
+export default CookieBanner;
diff --git a/src/app/components/CookieBanner/index.stories.jsx b/src/app/components/CookieBanner/index.stories.jsx
new file mode 100644
index 00000000000..5d725391458
--- /dev/null
+++ b/src/app/components/CookieBanner/index.stories.jsx
@@ -0,0 +1,4 @@
+import { storiesOf } from '@storybook/react'; // eslint-disable-line import/no-extraneous-dependencies
+import CookieBanner from '.';
+
+storiesOf('CookieBanner', module).add('default', () => CookieBanner);

From 8e0208c2a16c5c9c4cb8bb206a91c64d029310aa Mon Sep 17 00:00:00 2001
From: Sareh Heidari <sareh.heidari@gmail.com>
Date: Fri, 15 Feb 2019 14:58:29 +0000
Subject: [PATCH 03/25] Initial consent banner container, only loading cookie
 banner for amp pages

---
 src/app/containers/ConsentBanner/index.jsx | 30 ++++++++++++++++++++++
 1 file changed, 30 insertions(+)
 create mode 100644 src/app/containers/ConsentBanner/index.jsx

diff --git a/src/app/containers/ConsentBanner/index.jsx b/src/app/containers/ConsentBanner/index.jsx
new file mode 100644
index 00000000000..5f671f8b9be
--- /dev/null
+++ b/src/app/containers/ConsentBanner/index.jsx
@@ -0,0 +1,30 @@
+import React from 'react';
+import CookieBanner from '../../components/CookieBanner';
+import { PlatformContextConsumer } from '../../contexts/PlatformContext';
+
+const ConsentBanner = () => (
+  <PlatformContextConsumer>
+    {platform => {
+      if (platform === 'amp') {
+        return (
+          <amp-consent id="amp-o-user-consent" layout="nodisplay">
+            <script type="application/json">
+              {/* {
+              "consents": {
+                "user-consent": {
+                  "promptIfUnknownForGeoGroup": "eu",
+                  "promptUI": "amp-o-user-consent-dialog"
+                }
+              }
+            } */}
+            </script>
+            <CookieBanner />
+          </amp-consent>
+        );
+      }
+      return null;
+    }}
+  </PlatformContextConsumer>
+);
+
+export default ConsentBanner;

